bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
r=/home/gace/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed/.releases/37d1ce2cd32ebf4c1fd7ca32a95add62443d191b/preview-instructions-no-fee-v7
image=create-videobot:preview-guide-v7-37d1ce2c-verified
test -s "$r/src/telegram/creatorUi.mjs" || exit 61
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 62
docker image inspect "$image" >/dev/null 2>&1 || exit 63
python3 -B - "$r" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1])
s=(p/'src/telegram/creatorUi.mjs').read_text()
if s.count('function creatorEditorPanelBase(')!=1:sys.exit(64)
q=p/'debugCreatorUi.mjs'
if q.exists():sys.exit(65)
q.write_text(s+'\nexport {creatorEditorPanelBase};\n')
PY
set +e
docker run --rm -i --network none -v "$r/debugCreatorUi.mjs:/opt/videobot/src/telegram/debugCreatorUi.mjs:ro" --entrypoint node "$image" --input-type=module <<'NODE'
import {openCreatorEditor,editCreatorDraft,creatorEditorPanelBase} from '/opt/videobot/src/telegram/debugCreatorUi.mjs';
const owner='112233';
let d=openCreatorEditor({sellerId:owner});
d=editCreatorDraft(d,{type:'captionTitle',text:'test'});
d=editCreatorDraft(d,{type:'paidVideo',media:{fileId:'video_123abc'}});
d=editCreatorDraft(d,{type:'thumbnail',media:{fileId:'photo_123abc'}});
d=editCreatorDraft(d,{type:'sample',media:{fileId:'sample_123abc',durationSeconds:22.8}});
d=editCreatorDraft(d,{type:'preset',stars:50});
const ed=openCreatorEditor({sellerId:owner,existing:{id:'test_video',sellerId:owner,revision:2,title:'test',priceStars:50,paidVideo:{fileId:'video_123abc'},thumbnail:{fileId:'photo_123abc'},sample:{fileId:'sample_123abc',durationSeconds:22.8},rightsVerified:true,adultConsentVerified:true,feeTermsAccepted:true}});
const c=creatorEditorPanelBase(d,7,'editor');
const e=creatorEditorPanelBase(ed,7,'editor');
const cbs=p=>p.reply_markup.inline_keyboard.flat().map(b=>String(b.callback_data||''));
const texts=p=>p.reply_markup.inline_keyboard.flat().map(b=>String(b.text||''));
const flags=[
 cbs(c).some(x=>x.startsWith('entry:register')),
 cbs(e).some(x=>x.startsWith('edit:save')),
 texts(c).some(x=>x.includes('投稿する')),
 texts(e).some(x=>x.includes('変更')),
 /販売手数料/.test(c.text),
 /販売手数料/.test(e.text)
];
const mask=flags.reduce((sum,flag,i)=>sum+(flag?(1<<i):0),0);
process.exit(100+mask);
NODE
code=$?
set -e
test "$code" -ge 100 && test "$code" -le 163 || exit 66
echo LIVE_VIDEO_PREVIEW_BUTTON_DIAGNOSTIC=CLASSIFIED
exit "$code"
